        text = text.replace(Regex("\\b(?:hoyeche|hoiche|hoicay|hoisay|haiche|hosche|hoicha|hocche|hoisen|hoicee|hoiasa|hoisee|hoyese|hoyche|hoyse|hoice|hoile|hoisy|hoisi|hyche|hoysa|hossa|hoyce|house|hoige|huice|hocce|hoica|hoisa|hoicy|haysa|hcce|hcse|hyse)\\b", RegexOption.IGNORE_CASE), "hoise")
        // Bengali: ভাড়া -> vara
        text = text.replace(Regex("\\b(?:bharar|bharay|varah|varar|bhara|vaada|bada)\\b", RegexOption.IGNORE_CASE), "vara")
        // Bengali: বাস -> bus
        text = text.replace(Regex("\\b(?:basai|buser|beshi|bashi|basha|bhasa|bassa|basay|basae|bash|basa|buje|bass|buse|besi|basi|buja|boss|baas|bas|but)\\b", RegexOption.IGNORE_CASE), "bus")
        // Bengali: রিকশা -> rickshaw
        text = text.replace(Regex("\\b(?:rikshaw|ricksha|ricksa|riksha|riksa)\\b", RegexOption.IGNORE_CASE), "rickshaw")
        // Bengali: সিএনজি -> cng
        text = text.replace(Regex("\\bc\\.n\\.g\\b", RegexOption.IGNORE_CASE), "cng")
        // Bengali: অটো -> auto
        text = text.replace(Regex("\\b(?:aita|otou|outo|akto|auro|atuo|ata|ato)\\b", RegexOption.IGNORE_CASE), "auto")
        // Bengali: ট্রেন -> train
        text = text.replace(Regex("\\b(?:traino|brain|trein)\\b", RegexOption.IGNORE_CASE), "train")
        // Bengali: মেট্রো -> metro
        text = text.replace(Regex("\\bmetroi\\b", RegexOption.IGNORE_CASE), "metro")
        // Bengali: গাড়ি -> gari
        text = text.replace(Regex("\\b(?:garir|gadi)\\b", RegexOption.IGNORE_CASE), "gari")
        // Bengali: খাবার -> khabar
        text = text.replace(Regex("\\b(?:khabaar|khabare)\\b", RegexOption.IGNORE_CASE), "khabar")
        // Bengali: নাস্তা -> nasta
        text = text.replace(Regex("\\b(?:nastah|nashta)\\b", RegexOption.IGNORE_CASE), "nasta")
        // Bengali: লাঞ্চ -> lunch
        text = text.replace(Regex("\\b(?:luncher|lanch)\\b", RegexOption.IGNORE_CASE), "lunch")
        // Bengali: ডিনার -> dinner
        text = text.replace(Regex("\\bdinar\\b", RegexOption.IGNORE_CASE), "dinner")
        // Bengali: ভাত -> bhat
        text = text.replace(Regex("\\b(?:bhatu|vaate|vaat|vhat|bat|vat)\\b", RegexOption.IGNORE_CASE), "bhat")
        // Bengali: বিরিয়ানি -> biryani
        text = text.replace(Regex("\\b(?:biriyani|biriani)\\b", RegexOption.IGNORE_CASE), "biryani")
        // Bengali: চা -> cha
        text = text.replace(Regex("\\b(?:chaoya|cheai|chaiy|chaay|cheye|chayy|chaii|chaoa|chaya|cayoa|icha|chat|chap|char|chai|ucha|acha|chaw|caia|chay|chea|chao|chal|chan|chsi|chas|sha|che|tea|chi|chk|chy|tha|kha|cpa|ca)\\b", RegexOption.IGNORE_CASE), "cha")
        // Bengali: কফি -> coffee
        text = text.replace(Regex("\\bcoffe\\b", RegexOption.IGNORE_CASE), "coffee")
        // Bengali: রুটি -> ruti
        text = text.replace(Regex("\\b(?:roote|truti|roti|tuti)\\b", RegexOption.IGNORE_CASE), "ruti")
        // Bengali: পরোটা -> parata
        text = text.replace(Regex("\\b(?:porata|porota)\\b", RegexOption.IGNORE_CASE), "parata")
        // Bengali: সিঙ্গারা -> singara
        text = text.replace(Regex("\\bshingara\\b", RegexOption.IGNORE_CASE), "singara")
        // Bengali: ফুচকা -> fuchka
        text = text.replace(Regex("\\bfuska\\b", RegexOption.IGNORE_CASE), "fuchka")
        // Bengali: বাজার -> bazar
        text = text.replace(Regex("\\b(?:bazaar|baazar|bajare|bazare|bajar)\\b", RegexOption.IGNORE_CASE), "bazar")
        // Bengali: চাল -> chal
        text = text.replace(Regex("\\b(?:chailaii|chailiye|chaaaaal|chaliyea|chailay|chalaya|chaliye|chaliya|chailai|chailo|chaile|chaili|chalie|chalau|chalia|cholle|chalai|chalay|school|chalk|chole|chaal|chlay|calai|shilo|chalo|chala|chilo|saale|calao|chila|calay|colle|caluu|chali|chalu|calea|calia|calo|chat|chap|chai|saal|char|chaw|calu|call|clai|chan|cha)\\b", RegexOption.IGNORE_CASE), "chal")
        // Bengali: ডাল -> dal
        text = text.replace(Regex("\\b(?:daal|dile|dall)\\b", RegexOption.IGNORE_CASE), "dal")
        // Bengali: তেল -> tel
        text = text.replace(Regex("\\b(?:atel|toil|tele|ten|oil)\\b", RegexOption.IGNORE_CASE), "tel")
        // Bengali: ডিম -> dim
        text = text.replace(Regex("\\b(?:dims|deem|odim|die)\\b", RegexOption.IGNORE_CASE), "dim")
        // Bengali: দুধ -> dudh
        text = text.replace(Regex("\\b(?:dudu|dod|dud)\\b", RegexOption.IGNORE_CASE), "dudh")
        // Bengali: মাছ -> mach
        text = text.replace(Regex("\\b(?:macher|maach|machi|maas|much)\\b", RegexOption.IGNORE_CASE), "mach")
        // Bengali: মাংস -> mangsho
        text = text.replace(Regex("\\bmangso\\b", RegexOption.IGNORE_CASE), "mangsho")
        // Bengali: মুরগি -> murgi
        text = text.replace(Regex("\\b(?:murgir|moorgi|morgi)\\b", RegexOption.IGNORE_CASE), "murgi")
        // Bengali: সবজি -> sobji
        text = text.replace(Regex("\\b(?:shobjee|shobji)\\b", RegexOption.IGNORE_CASE), "sobji")
        // Bengali: আলু -> aloo
        text = text.replace(Regex("\\balu\\b", RegexOption.IGNORE_CASE), "aloo")
        // Bengali: পেঁয়াজ -> peyaj
        text = text.replace(Regex("\\b(?:piyaj|peaj)\\b", RegexOption.IGNORE_CASE), "peyaj")
        // Bengali: রসুন -> roshun
        text = text.replace(Regex("\\brosun\\b", RegexOption.IGNORE_CASE), "roshun")
        // Bengali: মরিচ -> morich
        text = text.replace(Regex("\\bmoris\\b", RegexOption.IGNORE_CASE), "morich")
        // Bengali: বিল -> bill
        text = text.replace(Regex("\\b(?:billy|bole|bola|boli|bil)\\b", RegexOption.IGNORE_CASE), "bill")
        // Bengali: বিদ্যুৎ -> biddut
        text = text.replace(Regex("\\b(?:bidyut|bidut)\\b", RegexOption.IGNORE_CASE), "biddut")
        // Bengali: কারেন্ট -> current
        text = text.replace(Regex("\\bkarent\\b", RegexOption.IGNORE_CASE), "current")
        // Bengali: গ্যাস -> gas
        text = text.replace(Regex("\\b(?:gyasiyo|gass)\\b", RegexOption.IGNORE_CASE), "gas")
        // Bengali: পানি -> pani
        text = text.replace(Regex("\\b(?:panio|panno|ponyo|paani|panir|bani|pane|pan)\\b", RegexOption.IGNORE_CASE), "pani")
        // Bengali: ওয়াইফাই -> wifi
        text = text.replace(Regex("\\b(?:wi\\-fi|wife)\\b", RegexOption.IGNORE_CASE), "wifi")
        // Bengali: ইন্টারনেট -> internet
        text = text.replace(Regex("\\b(?:internate|5internet|intarnet|intrnet|interet|nternet|net)\\b", RegexOption.IGNORE_CASE), "internet")
        // Bengali: রিচার্জ -> recharge
        text = text.replace(Regex("\\b(?:reacharge|reacherge|rrecharge|recherge|rechatge|recharg|recarge|rechrge|rechrg|ricarg|rchrg|rcrg)\\b", RegexOption.IGNORE_CASE), "recharge")
        // Bengali: লোড -> load
        text = text.replace(Regex("\\b(?:flaxiload|flexi|dload|lode|coad|lod)\\b", RegexOption.IGNORE_CASE), "load")
        // Bengali: বাসা -> basha
        text = text.replace(Regex("\\b(?:bashar|bassai|bhasa|basai|bassa|basay|basae|vasay|vasa|basa|bass|boss)\\b", RegexOption.IGNORE_CASE), "basha")
        // Bengali: বিকাশ -> bkash
        text = text.replace(Regex("\\b(?:bikashe|bkashe|bikash|bekash|bikas|bkas|bksh)\\b", RegexOption.IGNORE_CASE), "bkash")
        // Bengali: নগদ -> nagad
        text = text.replace(Regex("\\b(?:nogode|nagade|nogod|nagat)\\b", RegexOption.IGNORE_CASE), "nagad")
        // Bengali: রকেট -> rocket
        text = text.replace(Regex("\\b(?:roket|rockt)\\b", RegexOption.IGNORE_CASE), "rocket")
        // Bengali: উপায় -> upay
        text = text.replace(Regex("\\b(?:upaiye|upaay|upaye|upye|upoy|upai)\\b", RegexOption.IGNORE_CASE), "upay")
        // Bengali: স্বপ্ন -> shwapno
        text = text.replace(Regex("\\b(?:swapno|shopno)\\b", RegexOption.IGNORE_CASE), "shwapno")
        // Bengali: ওষুধ -> osudh
        text = text.replace(Regex("\\b(?:medicine|oiosudh|oushudh|oushodh|oshudh|ousodh)\\b", RegexOption.IGNORE_CASE), "osudh")
        // Bengali: ডাক্তার -> doctor
        text = text.replace(Regex("\\b(?:doctorra|daktar)\\b", RegexOption.IGNORE_CASE), "doctor")
        // Bengali: হাসপাতাল -> hospital
        text = text.replace(Regex("\\b(?:haspatale|haspatal)\\b", RegexOption.IGNORE_CASE), "hospital")
        // Bengali: শপিং -> shopping
        text = text.replace(Regex("\\bshoping\\b", RegexOption.IGNORE_CASE), "shopping")
        // Bengali: জামা -> jama
        text = text.replace(Regex("\\b(?:jamar|jaman|jamai|jamat)\\b", RegexOption.IGNORE_CASE), "jama")
        // Bengali: কাপড় -> kapor
        text = text.replace(Regex("\\b(?:kaporer|kapore|kapod)\\b", RegexOption.IGNORE_CASE), "kapor")
        // Bengali: বেতন -> beton
        text = text.replace(Regex("\\b(?:veton|betan)\\b", RegexOption.IGNORE_CASE), "beton")
        // Bengali: ইনকাম -> income
        text = text.replace(Regex("\\b(?:incoome|incomee|incomer|invome|incam|icome|incom|incm)\\b", RegexOption.IGNORE_CASE), "income")
        // Bengali: বোনাস -> bonus
        text = text.replace(Regex("\\b(?:bounas|bonous|bonas)\\b", RegexOption.IGNORE_CASE), "bonus")
        // Bengali: আজকে -> ajke
        text = text.replace(Regex("\\b(?:aijka|aajke|ajkeo|ajkey|ajkai|ajkei|ajhke|ajkea|ajkao|ajker|aske|ajka|ajko|ajk)\\b", RegexOption.IGNORE_CASE), "ajke")
        // Bengali: আজ -> aj
        text = text.replace(Regex("\\b(?:aajo|ajai|aju|ajb|ajk|aje|aji|ajo|aaj|ajj|kaj|aja|as|az)\\b", RegexOption.IGNORE_CASE), "aj")
        // Bengali: কালকে -> kalke
        text = text.replace(Regex("\\b(?:kalkeo|kalker|kalkei|kaalke|kalka|kalkk|kalk|klk)\\b", RegexOption.IGNORE_CASE), "kalke")
        // Bengali: গতকাল -> gotokal
        text = text.replace(Regex("\\b(?:gotokaler|gotokalke|gottkal|gotokl)\\b", RegexOption.IGNORE_CASE), "gotokal")
        // Bengali: পরশু -> porshu
        text = text.replace(Regex("\\b(?:porso|porsu|prsu)\\b", RegexOption.IGNORE_CASE), "porshu")
        // Bengali: তারিখ -> tarikh
        text = text.replace(Regex("\\b(?:tarikheo|tarikhei|tarikhe|tarike|tariik|tarika|tarkh|tarik|tarek|trik)\\b", RegexOption.IGNORE_CASE), "tarikh")
        // Bengali: কত -> koto
        text = text.replace(Regex("\\b(?:kotok|kosto|kotoi|kotob|kotoo|koyta|kotai|khoto|khoti|kotoy|kotou|kutta|khota|kotto|korto|kooto|kotho|khete|joto|kita|ksto|hoto|khot|moto|kate|coto|kotw|kete|kote|koro|kotu|kota|kato|kto|kot|oto)\\b", RegexOption.IGNORE_CASE), "koto")
        // Bengali: হিসাব -> hisab
        text = text.replace(Regex("\\b(?:heshabe|hishebe|hishabe|hisebeo|hishab|hiseba|hisabe|hosebe|hisebe|hiseb|hisan)\\b", RegexOption.IGNORE_CASE), "hisab")
        // Bengali: ব্যালেন্স -> balance
        text = text.replace(Regex("\\b(?:balence|blence|blance|balace|balens|blnc)\\b", RegexOption.IGNORE_CASE), "balance")
        // Bengali: মোট -> mot
        text = text.replace(Regex("\\b(?:moteo|mota|mote|moti|muta|moth|moto|motu|muti|emot|dot|mod|mut)\\b", RegexOption.IGNORE_CASE), "mot")
        // Bengali: সবচেয়ে -> shobcheye
        text = text.replace(Regex("\\b(?:sobcheye|sabcheye|shbcheye|shobche|sobceye|sbceye|sobche)\\b", RegexOption.IGNORE_CASE), "shobcheye")
        // Bengali: বাকি -> baki
        text = text.replace(Regex("\\bbai\\b", RegexOption.IGNORE_CASE), "baki")
        return text
    }

}
